import React, { useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import StaffNavbar from '../components/StaffNavbar';

/* HERO */
function Banner() {
  return (
    <div className="relative w-full h-[500px] bg-[#1a1a1a] flex items-center justify-center overflow-hidden font-['DM_Sans']">

      <div
        className="absolute inset-0 opacity-40 bg-cover bg-center"
        style={{
          backgroundImage:
            "url('https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?q=80&w=2000')",
        }}
      />

      <div className="relative z-10 text-center px-6 max-w-4xl">

        <motion.h1 className="text-white text-6xl font-bold">
          Staff <span className="text-[#d4af37]">Dashboard</span>
        </motion.h1>

        <p className="text-gray-300 mt-4">
          Manage orders, products, and customers.
        </p>

      </div>

    </div>
  );
}

/* STATS */
function StatsCard({ title, value }) {
  return (
    <motion.div className="bg-white rounded-[30px] shadow-xl p-8">
      <p className="text-gray-400 text-xs uppercase">{title}</p>
      <h2 className="text-4xl font-bold">{value}</h2>
    </motion.div>
  );
}

export default function DashboardStaff() {

  const [products, setProducts] = useState([]);

  useEffect(() => {
    fetch("http://localhost/pastry_system/customer/api_products.php?action=list")
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setProducts(data);
      })
      .catch(() => setProducts([]));
  }, []);

  const cakes = useMemo(
    () => products.filter(p => p.category?.toLowerCase() === 'cakes'),
    [products]
  );

  const pastries = useMemo(
    () => products.filter(p => p.category?.toLowerCase() !== 'cakes'),
    [products]
  );

  return (

    <div className="bg-[#fafafa] min-h-screen font-['DM_Sans'] pt-[100px]">

      <StaffNavbar />

      <Banner />

      <div className="max-w-7xl mx-auto px-10 py-14">

        {/* STATS */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-20">

          <StatsCard title="Total Products" value={products.length} />
          <StatsCard title="Cake Products" value={cakes.length} />
          <StatsCard title="Pastries" value={pastries.length} />
          <StatsCard title="Orders Today" value="24" />

        </div>

        {/* PRODUCTS */}
        <section>

          <h2 className="text-3xl font-bold mb-6">
            Available Products
          </h2>

          <div className="bg-white rounded-[40px] shadow-2xl p-10">

            {products.slice(0, 10).map(product => (
              <div key={product.id} className="flex justify-between border-b py-4">

                <div>
                  <p className="font-bold">{product.name}</p>
                  <p className="text-gray-500 text-sm">{product.category}</p>
                </div>

                <p className="font-bold">₱{product.price}</p>

              </div>
            ))}

          </div>

        </section>

      </div>

    </div>

  );
}
